SELECT DISTINCT FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, MST_FEEINFO.FEE_NAME feeName, FIN_FLOAT_CALC_RULE_DETAIL.LEV lev, FIN_FLOAT_CALC_RULE_DETAIL.COEFFICIENT coefficient, FIN_FLOAT_CALC_RULE_DETAIL.SPREAD_RATE*100 spreadRate, FIN_FLOAT_CALC_RULE_DETAIL.CHARGE_RATIO*100 chargeRatio, FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE effDate, FIN_CASH_INFO.CASH_ID cashId, FIN_PRODUCT.FINPROD_ID finprodId, '0.0' intRate, FIN_FLOAT_CALC_RULE.BASE_RULE baseRule, PRD_LAYER_PARAM.Prod_Style prodStyle,
INF_FIN_FLOAT_CALC_RULE.SEND_STATUS sendStatus, INF_FIN_FLOAT_CALC_RULE.SEND_REMARK sendRemark ,fin_product_add.INVESTMENT_CYCLE investmentCycle
,nvl(FIN_PRODUCT.p_finprod_id, FIN_PRODUCT.finprod_id) pfinprodid
FROM FIN_PRODUCT LEFT JOIN PRD_LAYER_PARAM ON PRD_LAYER_PARAM.FINPROD_ID =FIN_PRODUCT.FINPROD_ID, FIN_BASE_RULE_INFO, FIN_FLOAT_CALC_RULE, FIN_FLOAT_CALC_RULE_DETAIL
LEFT JOIN INF_FIN_FLOAT_CALC_RULE ON FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID =INF_FIN_FLOAT_CALC_RULE.CASH_ID AND FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE =INF_FIN_FLOAT_CALC_RULE.EFF_DATE,
MST_FEEINFO, FIN_CASH_INFO, fin_product_add, PTL_PORTFOLIO_AUTHORITY WHERE FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID AND FIN_PRODUCT.FINPROD_ID = FIN_BASE_RULE_INFO.FINPROD_ID AND FIN_PRODUCT.FINPROD_TYPE = #{finprodType2} AND FIN_PRODUCT.PROFIT_TYPE IN
#{item,jdbcType=VARCHAR}
AND FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID AND FIN_CASH_INFO.CASH_ID = FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID AND FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2} AND FIN_FLOAT_CALC_RULE.CASH_ID = FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID AND FIN_FLOAT_CALC_RULE.EFF_DATE = FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE AND fin_product_add.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND fin_product_add.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND FIN_CASH_INFO.BRANCH = 0
AND FIN_PRODUCT_ADD.Issue_Status=#{issueStatus}
AND( FIN_PRODUCT.FINPROD_ID IN(
#{item}
) OR FIN_PRODUCT.P_FINPROD_ID IN(
#{item}
) )
AND FIN_PRODUCT.FINPROD_ID IN(
#{item}
)
AND to_char(FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE,'yyyy-MM-dd') >= #{effDateStart}
AND to_char(FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE,'yyyy-MM-dd') <= #{effDateEnd}
#{key,jdbcType=VARCHAR}
ORDER BY FIN_PRODUCT.FINPROD_ID ASC, FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE DESC,FIN_FLOAT_CALC_RULE_DETAIL.LEV ASC

SELECT A.INDEX_ID indexId, A.INDEX_SOURCE indexSource, A.BASE_RULE_ID baseRuleId FROM FIN_BASE_RULE_INFO A WHERE A.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} AND to_char(A.EFF_DATE,'yyyy-MM-dd') <= #{effDate}
AND A.Base_Rule_Type = #{BASE_RULE_TYPE_02}
ORDER BY A.EFF_DATE DESC

SELECT DISTINCT FIN_PRODUCT.FINPROD_ID id,
FIN_PRODUCT.FINPROD_MARKET_ID ||':'|| FIN_PRODUCT.FINPROD_ABBR text, FIN_PRODUCT.FINPROD_MARKET_ID || ',' || FIN_PRODUCT_ADD.DEAL_MODE object, FIN_PRODUCT.VDATE col FROM FIN_PRODUCT, PTL_MANAGE_OBJ, PTL_PORTFOLIO_AUTHORITY, FIN_PRODUCT_ADD
FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2} AND PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID AND PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
AND FIN_PRODUCT_ADD.Issue_Status=#{issueStatus}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
AND FIN_PRODUCT.PROFIT_TYPE IN(
#{item}
)
AND (FIN_PRODUCT.FINPROD_ID like concat(concat('%', #{search,jdbcType=VARCHAR}),'%') OR FIN_PRODUCT.FINPROD_ABBR like concat(concat('%', #{search,jdbcType=VARCHAR}),'%'))
AND FIN_PRODUCT.FINPROD_ID = #{initValue}

SELECT FEE_ID id, FEE_NAME text, MST_FEEINFO.BASIC_BILL object, MST_FEEINFO.BASIS col FROM MST_FEEINFO
FEE_TYPE = #{feeType}
AND (FEE_ID like concat(concat('%', #{feeId,jdbcType=VARCHAR}),'%') OR FEE_NAME like concat(concat('%', #{feeId,jdbcType=VARCHAR}),'%'))

SELECT FIN_FLOAT_CALC_RULE_DETAIL.LEV lev, FIN_FLOAT_CALC_RULE_DETAIL.SPREAD_RATE*100 spreadRate, FIN_FLOAT_CALC_RULE_DETAIL.BASE_RULE_ID baseRuleId, FIN_FLOAT_CALC_RULE_DETAIL.COEFFICIENT coefficient, FIN_FLOAT_CALC_RULE_DETAIL.CHARGE_RATIO*100 chargeRatio FROM FIN_FLOAT_CALC_RULE_DETAIL
FIN_FLOAT_CALC_RULE_DETAIL.CASH_ID = #{cashId}
AND FIN_FLOAT_CALC_RULE_DETAIL.LEV = #{lev}
AND FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE = (select min(eff_date) from FIN_FLOAT_CALC_RULE_DETAIL where cash_id=#{cashId})
AND to_char(FIN_FLOAT_CALC_RULE_DETAIL.EFF_DATE,'yyyy-MM-dd') = #{effDate}
ORDER BY FIN_FLOAT_CALC_RULE_DETAIL.LEV ASC

SELECT SUM(A.count) count 
FROM
(SELECT
	COUNT(*) as count
FROM
	FIN_CASH_INFO,
	FIN_FLOAT_COUNTING_RULE
WHERE
	FIN_CASH_INFO.FINPROD_ID = 	#{finprodId}
	AND FIN_CASH_INFO.CASH_ID =	FIN_FLOAT_COUNTING_RULE.CASH_ID
	AND FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
	 AND to_char(FIN_FLOAT_COUNTING_RULE.EFF_DATE,'yyyy-MM-dd')  > #{effDate} 
UNION ALL
SELECT
	COUNT(*) as count
FROM 
	FIN_CASH_INFO,
	FIN_CASH_PAY_RULE

    FIN_CASH_INFO.FINPROD_ID = 	#{finprodId}
    AND FIN_CASH_INFO.CASH_ID =	FIN_CASH_PAY_RULE.CASH_ID	
    AND	FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
     AND to_char(FIN_CASH_PAY_RULE.EFF_DATE,'yyyy-MM-dd')  > #{effDate} 
)A

SELECT FIN_PRODUCT.FINPROD_ABBR finprodAbbr, FIN_PRODUCT.FINPROD_ID finprodId, MST_FEEINFO.FEE_NAME feeName, MST_FEEINFO.FEE_ID feeId, MST_FEEINFO.BASIC_BILL basicBill, MST_FEEINFO.BASIS basis, FIN_CASH_INFO.CASH_ID cashId, FIN_FLOAT_CALC_RULE.AST_VDATE_TYPE astVdateType, FIN_FLOAT_COUNTING_RULE.F_ACCR_DATE fAccrDate, FIN_FLOAT_CALC_RULE.EFF_DATE effDate,
FIN_FLOAT_CALC_RULE.BASE_RULE baseRule, FIN_FLOAT_CALC_RULE.REMARK remark,
FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE eAccrDate, FIN_FLOAT_COUNTING_RULE.ACCR_TYPE accrType, FIN_FLOAT_COUNTING_RULE.INTERVAL_RULE intervalRule, FIN_FLOAT_COUNTING_RULE.ACCR_TDAY_RULE accrTdayRule, FIN_FLOAT_COUNTING_RULE.F_ACCR_END_DATE fAccrEndDate, FIN_CASH_PAY_RULE.PAY_CYCLE payCycle, FIN_CASH_PAY_RULE.FIRST_PAY_DATE firstPayDate, FIN_CASH_PAY_RULE.END_TDAY_RULE endTdayRule, FIN_CASH_PAY_RULE.PAY_TDAY_RULE payTdayRule, FIN_PRODUCT.P_FINPROD_ID pFinprodId ,FIN_PRODUCT.FINPROD_market_ID finprodMarketId ,PRD_LAYER_PARAM.Prod_Style prodStyle ,FIN_PRODUCT_ADD.DEAL_MODE dealMode FROM FIN_PRODUCT LEFT JOIN PRD_LAYER_PARAM ON PRD_LAYER_PARAM.FINPROD_ID =FIN_PRODUCT.FINPROD_ID, MST_FEEINFO, FIN_FLOAT_CALC_RULE, FIN_FLOAT_COUNTING_RULE, FIN_CASH_INFO,
FIN_CASH_PAY_RULE, FIN_PRODUCT_ADD
FIN_PRODUCT.FINPROD_ID = #{finprodId} AND FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2} AND FIN_CASH_INFO.CASH_ID =FIN_FLOAT_CALC_RULE.CASH_ID AND FIN_CASH_INFO.CASH_ID = FIN_FLOAT_COUNTING_RULE.CASH_ID AND FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND FIN_CASH_PAY_RULE.EFF_DATE=FIN_FLOAT_CALC_RULE.EFF_DATE AND FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
AND FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
AND FIN_CASH_INFO.CASH_ID = FIN_FLOAT_COUNTING_RULE.CASH_ID AND FIN_FLOAT_COUNTING_RULE.EFF_DATE=FIN_FLOAT_CALC_RULE.EFF_DATE AND FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID
AND FIN_FLOAT_CALC_RULE.CASH_ID = #{cashId}
AND FIN_PRODUCT_ADD.INVESTMENT_CYCLE = #{investmentCycle}
AND to_char(FIN_FLOAT_CALC_RULE.EFF_DATE,'yyyy-MM-dd') = #{effDate}

